mapper.select:
select jr.id as id,jr.user_id as userId,jr.name as name,jr.phone as phone,jr.avatar as avatar,jr.percentage as percentage,jr.personal_skill as personalSkill,jr.sex as sex,jr.birthday as birthday,jr.personal_skill as persionSkill, jr.skills as skills,jr.work_year as workYear,jr.job_status as jobStatus,jr.address as address,jr.address_name as addressName,jr.address_lat as addressLat,jr.address_lng as addressLng,jr.create_time as createTime, jri.type_names as typeNames,jri.type_ids as typeIds,jri.employ_method as employMethod,jri.settlement_type as settlementType,jri.work_city as workCity,jri.work_type as workType,jri.expect_salary as expectSalary,jri.salary_unit as salaryUnit, ura.realname as realName,su.update_time as loginTime,je.score as score from job_resume jr left join job_resume_intention jri on jri.user_id=jr.user_id LEFT JOIN ums_realname_auth ura on ura.user_id = jr.user_id and ura.auth_status =1 left join sys_user su on su.id = jr.user_id left join job_evaluate je on je.user_id = jr.user_id and je.role_code = 'member' WHERE 1=1
AND jr.sex = #{params.sex}
AND jr.user_id = #{params.userId}
AND jr.job_status = #{params.jobStatus}
AND jr.city_code = #{params.cityCode}
AND FIND_IN_SET(#{params.typeIds},jri.type_ids)
and ( jr.name like CONCAT('%',#{params.keyword},'%') or jr.phone like CONCAT('%',#{params.keyword},'%') or jr.personal_skill like CONCAT('%',#{params.keyword},'%') )
order by jr.create_time desc
